      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Their theoretical foundations for trapped-ion quantum computing and atomic quantum simulation transformed quantum information from an abstract proposal into a concrete experimental programme.",
        "attribution": "Cirac and Zoller are appropriately paired for the central theoretical proposals and framework that guided the field.",
        "maturity": "Trapped-ion control and quantum simulation have been demonstrated extensively, although scalable fault-tolerant computing remains unfinished.",
        "uncertainties": [
          "The award boundary between foundational theory and later experimental advances would need careful definition."
        ]
      }
    },
